/* Run existing authenticated social flows with the real dark palette. */
const fs=require('node:fs'),{chromium}=require('playwright'),audit=require('./contrast-audit.cjs'),launch=chromium.launch.bind(chromium);let failures=[],captures=0;
chromium.launch=async(...args)=>{const browser=await launch(...args),newContext=browser.newContext.bind(browser),close=browser.close.bind(browser);browser.newContext=async(...args)=>{const c=await newContext(...args);await c.addInitScript(()=>{try{localStorage.setItem('break-room:theme','dark');}catch{}});const newPage=c.newPage.bind(c);c.newPage=async(...args)=>{const p=await newPage(...args),screenshot=p.screenshot.bind(p);p.screenshot=async(...args)=>{if(await p.evaluate(()=>document.documentElement.dataset.theme==='dark')){captures++;failures.push(...(await p.evaluate(audit)).map(x=>({...x,url:p.url(),width:p.viewportSize().width})));}return screenshot(...args);};return p;};return c;};browser.close=async()=>{await close();fs.writeFileSync(process.env.BR_DARK_SOCIAL_REPORT,JSON.stringify({captures,failures},null,2));if(failures.length)throw Error('Dark social contrast failures: '+JSON.stringify(failures));};return browser;};
